parameters.text:
=
You are a B2B Sales Intelligence Analyst.

Analyze the incoming lead and available company website content.

LEAD INFORMATION:
Name: {{$json.fullName}}
Email: {{$json.email}}
Company: {{$json.company}}
Job Title: {{$json.jobTitle}}
Industry: {{$json.industry}}
Country: {{$json.country}}
Product Interest: {{$json.product}}
Website: {{$json.website}}
Lead Score: {{$json.leadScore}}

COMPANY WEBSITE CONTENT:
{{$json.websiteContent}}

Your task is to generate useful sales intelligence for the sales team.

Analyze:
1. Company overview and business model.
2. Likely business challenges.
3. Potential use cases for the product they are interested in.
4. Buying intent and decision-maker relevance.
5. Recommended sales approach.
6. A personalized first-touch outreach message.

Use only evidence supported by the available information. Clearly identify assumptions and unknowns. Do not invent company facts.

Return the result in a clear, structured format with these sections:
- Company Overview
- Business Challenges
- Potential Use Cases
- Buying Intent
- Recommended Sales Approach
- Personalized Outreach

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "companyOverview": { "type": "string", "description": "2-3 sentences, based on website content" },
    "businessModel": { "type": "string", "description": "How the company makes money" },
    "likelyChallenges": { "type": "array", "items": { "type": "string" }, "description": "3-4 items tied to the lead's industry and size" },
    "potentialUseCases": { "type": "array", "items": { "type": "string" }, "description": "3-4 items tied to the lead's product interest" },
    "buyingIntent": { "type": "string", "enum": ["High", "Medium", "Low", "Unknown"] },
    "decisionMakerRelevance": { "type": "string", "description": "Based on job title and company size" },
    "recommendedSalesApproach": { "type": "string" },
    "personalizedOutreach": { "type": "string", "description": "Ready-to-send email with subject line. No bracketed placeholders." },
    "confidence": { "type": "string", "enum": ["High", "Medium", "Low"] },
    "evidenceAndUnknowns": { "type": "array", "items": { "type": "string" }, "description": "Prefix each item with Evidence:, Unknown: or Assumption:" }
  },
  "required": ["companyOverview", "businessModel", "likelyChallenges", "potentialUseCases", "buyingIntent", "decisionMakerRelevance", "recommendedSalesApproach", "personalizedOutreach", "confidence", "evidenceAndUnknowns"]
}

parameters.jsCode:
const lead = $('Normalize Lead').item.json;

const html = String($json.data || '');

// Prefer <main>; fall back to <body>
const mainMatch = html.match(/<main[\s\S]*?<\/main>/i);
const body = mainMatch ? mainMatch[0] : html;

// Pull the page title and meta description separately
const title = (html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || '';
const desc = (html.match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i) || [])[1] || '';

const text = body
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<svg[\s\S]*?<\/svg>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&#x27;/g, "'")
  .replace(/\s+/g, ' ')
  .trim();

const pageText = [title, desc, text].filter(Boolean).join(' | ').slice(0, 5000);

return {
  json: {
    ...lead,
    pageText: pageText || 'No website content could be retrieved.'
  }
};

const lead = $('Basic AI Input').item.json;
const { pageText, ...leadClean } = lead;

return {
  json: {
    ...leadClean,
    enrichment: $json.output
  }
};
